56	/**
57	 * This class implements debug operations on the HDFS command-line.
58	 *
59	 * These operations are only for debugging, and may change or disappear
60	 * between HDFS versions.
61	 */
62	@InterfaceAudience.Private
63	@InterfaceStability.Evolving
64	public class DebugAdmin extends Configured implements Tool {
65	  /**
66	   * All the debug commands we can run.
67	   */
68	  private final DebugCommand[] DEBUG_COMMANDS = {
69	      new VerifyMetaCommand(),
70	      new ComputeMetaCommand(),
71	      new RecoverLeaseCommand(),
72	      new HelpCommand()
73	  };
