75	  /**
76	   * The base class for debug commands.
77	   */
78	  private abstract static class DebugCommand {
79	    final String name;
80	    final String usageText;
81	    final String helpText;
82	
83	    DebugCommand(String name, String usageText, String helpText) {
84	      this.name = name;
85	      this.usageText = usageText;
86	      this.helpText = helpText;
87	    }
88	
89	    abstract int run(List<String> args) throws IOException;
90	  }
91	
92	  private static int HEADER_LEN = 7;
93	
94	  /**
95	   * The command for verifying a block metadata file and possibly block file.
96	   */
97	  private static class VerifyMetaCommand extends DebugCommand {
98	    VerifyMetaCommand() {
99	      super("verifyMeta",
100	          "verifyMeta -meta <metadata-file> [-block <block-file>]",
101	          "  Verify HDFS metadata and block files.  If a block file is specified, we" +
102	              System.lineSeparator() +
103	              "  will verify that the checksums in the metadata file match the block" +
104	              System.lineSeparator() +
105	              "  file.");
106	    }
107	
108	    int run(List<String> args) throws IOException {
109	      if (args.size() == 0) {
110	        System.out.println(usageText);
111	        System.out.println(helpText + System.lineSeparator());
112	        return 1;
113	      }
114	      String blockFile = StringUtils.popOptionWithArgument("-block", args);
115	      String metaFile = StringUtils.popOptionWithArgument("-meta", args);
116	      if (metaFile == null) {
117	        System.err.println("You must specify a meta file with -meta");
118	        return 1;
119	      }
120	
121	      FileInputStream metaStream = null, dataStream = null;
122	      FileChannel metaChannel = null, dataChannel = null;
123	      DataInputStream checksumStream = null;
124	      try {
125	        BlockMetadataHeader header;
126	        try {
127	          metaStream = new FileInputStream(metaFile);
128	          checksumStream = new DataInputStream(metaStream);
129	          header = BlockMetadataHeader.readHeader(checksumStream);
130	          metaChannel = metaStream.getChannel();
131	          metaChannel.position(HEADER_LEN);
132	        } catch (RuntimeException e) {
133	          System.err.println("Failed to read HDFS metadata file header for " +
134	              metaFile + ": " + StringUtils.stringifyException(e));
135	          return 1;
136	        } catch (IOException e) {
137	          System.err.println("Failed to read HDFS metadata file header for " +
138	              metaFile + ": " + StringUtils.stringifyException(e));
139	          return 1;
140	        }
141	        DataChecksum checksum = header.getChecksum();
142	        System.out.println("Checksum type: " + checksum.toString());
143	        if (blockFile == null) {
144	          return 0;
145	        }
146	        ByteBuffer metaBuf, dataBuf;
147	        try {
148	          dataStream = new FileInputStream(blockFile);
149	          dataChannel = dataStream.getChannel();
150	          final int CHECKSUMS_PER_BUF = 1024 * 32;
151	          metaBuf = ByteBuffer.allocate(checksum.
152	              getChecksumSize() * CHECKSUMS_PER_BUF);
153	          dataBuf = ByteBuffer.allocate(checksum.
154	              getBytesPerChecksum() * CHECKSUMS_PER_BUF);
155	        } catch (IOException e) {
156	          System.err.println("Failed to open HDFS block file for " +
157	              blockFile + ": " + StringUtils.stringifyException(e));
158	          return 1;
159	        }
160	        long offset = 0;
161	        while (true) {
162	          dataBuf.clear();
163	          int dataRead = -1;
164	          try {
165	            dataRead = dataChannel.read(dataBuf);
166	            if (dataRead < 0) {
167	              break;
168	            }
169	          } catch (IOException e) {
170	            System.err.println("Got I/O error reading block file " +
171	                blockFile + "from disk at offset " + dataChannel.position() +
172	                ": " + StringUtils.stringifyException(e));
173	            return 1;
174	          }
175	          try {
176	            int csumToRead =
177	                (((checksum.getBytesPerChecksum() - 1) + dataRead) /
178	                  checksum.getBytesPerChecksum()) *
179	                      checksum.getChecksumSize();
180	            metaBuf.clear();
181	            metaBuf.limit(csumToRead);
182	            metaChannel.read(metaBuf);
183	            dataBuf.flip();
184	            metaBuf.flip();
185	          } catch (IOException e) {
186	            System.err.println("Got I/O error reading metadata file " +
187	                metaFile + "from disk at offset " + metaChannel.position() +
188	                ": " +  StringUtils.stringifyException(e));
189	            return 1;
190	          }
191	          try {
192	            checksum.verifyChunkedSums(dataBuf, metaBuf,
193	                blockFile, offset);
194	          } catch (IOException e) {
195	            System.out.println("verifyChunkedSums error: " +
196	                StringUtils.stringifyException(e));
197	            return 1;
198	          }
199	          offset += dataRead;
200	        }
201	        System.out.println("Checksum verification succeeded on block file " +
202	            blockFile);
203	        return 0;
204	      } finally {
205	        IOUtils.cleanupWithLogger(null, metaStream, dataStream, checksumStream);
206	      }
207	    }
208	  }
