210	  /**
211	   * The command for verifying a block metadata file and possibly block file.
212	   */
213	  private static class ComputeMetaCommand extends DebugCommand {
214	    ComputeMetaCommand() {
215	      super("computeMeta",
216	          "computeMeta -block <block-file> -out <output-metadata-file>",
217	          "  Compute HDFS metadata from the specified block file, and save it"
218	              + " to" + System.lineSeparator()
219	              + "  the specified output metadata file."
220	              + System.lineSeparator() + System.lineSeparator()
221	              + "**NOTE: Use at your own risk!" + System.lineSeparator()
222	              + " If the block file is corrupt"
223	              + " and you overwrite it's meta file, " + System.lineSeparator()
224	              + " it will show up"
225	              + " as good in HDFS, but you can't read the data."
226	              + System.lineSeparator()
227	              + " Only use as a last measure, and when you are 100% certain"
228	              + " the block file is good.");
229	    }
230	
231	    private DataChecksum createChecksum(Options.ChecksumOpt opt) {
232	      DataChecksum dataChecksum = DataChecksum
233	          .newDataChecksum(opt.getChecksumType(), opt.getBytesPerChecksum());
234	      if (dataChecksum == null) {
235	        throw new HadoopIllegalArgumentException(
236	            "Invalid checksum type: userOpt=" + opt + ", default=" + opt
237	                + ", effective=null");
238	      }
239	      return dataChecksum;
240	    }
241	
242	    int run(List<String> args) throws IOException {
243	      if (args.size() == 0) {
244	        System.out.println(usageText);
245	        System.out.println(helpText + System.lineSeparator());
246	        return 1;
247	      }
248	      final String name = StringUtils.popOptionWithArgument("-block", args);
249	      if (name == null) {
250	        System.err.println("You must specify a block file with -block");
251	        return 2;
252	      }
253	      final File blockFile = new File(name);
254	      if (!blockFile.exists() || !blockFile.isFile()) {
255	        System.err.println("Block file <" + name + "> does not exist "
256	            + "or is not a file");
257	        return 3;
258	      }
259	      final String outFile = StringUtils.popOptionWithArgument("-out", args);
260	      if (outFile == null) {
261	        System.err.println("You must specify a output file with -out");
262	        return 4;
263	      }
264	      final File srcMeta = new File(outFile);
265	      if (srcMeta.exists()) {
266	        System.err.println("output file already exists!");
267	        return 5;
268	      }
269	
270	      DataOutputStream metaOut = null;
271	      try {
272	        final Configuration conf = new Configuration();
273	        final Options.ChecksumOpt checksumOpt =
274	            DfsClientConf.getChecksumOptFromConf(conf);
275	        final DataChecksum checksum = createChecksum(checksumOpt);
276	
277	        final int smallBufferSize = DFSUtilClient.getSmallBufferSize(conf);
278	        metaOut = new DataOutputStream(
279	            new BufferedOutputStream(Files.newOutputStream(srcMeta.toPath()),
280	                smallBufferSize));
281	        BlockMetadataHeader.writeHeader(metaOut, checksum);
282	        metaOut.close();
283	        FsDatasetUtil.computeChecksum(
284	            srcMeta, srcMeta, blockFile, smallBufferSize, conf);
285	        System.out.println(
286	            "Checksum calculation succeeded on block file " + name
287	                + " saved metadata to meta file " + outFile);
288	        return 0;
289	      } finally {
290	        IOUtils.cleanupWithLogger(null, metaOut);
291	      }
292	    }
293	  }
