295	  /**
296	   * The command for recovering a file lease.
297	   */
298	  private class RecoverLeaseCommand extends DebugCommand {
299	    RecoverLeaseCommand() {
300	      super("recoverLease",
301	"recoverLease -path <path> [-retries <num-retries>]",
302	"  Recover the lease on the specified path.  The path must reside on an" +
303	    System.lineSeparator() +
304	"  HDFS filesystem.  The default number of retries is 1.");
305	    }
306	
307	    private static final int TIMEOUT_MS = 5000;
308	
309	    int run(List<String> args) throws IOException {
310	      if (args.size() == 0) {
311	        System.out.println(usageText);
312	        System.out.println(helpText + System.lineSeparator());
313	        return 1;
314	      }
315	      String pathStr = StringUtils.popOptionWithArgument("-path", args);
316	      String retriesStr = StringUtils.popOptionWithArgument("-retries", args);
317	      if (pathStr == null) {
318	        System.err.println("You must supply a -path argument to " +
319	            "recoverLease.");
320	        return 1;
321	      }
322	      int maxRetries = 1;
323	      if (retriesStr != null) {
324	        try {
325	          maxRetries = Integer.parseInt(retriesStr);
326	        } catch (NumberFormatException e) {
327	          System.err.println("Failed to parse the argument to -retries: " +
328	              StringUtils.stringifyException(e));
329	          return 1;
330	        }
331	      }
332	      FileSystem fs;
333	      try {
334	        fs = FileSystem.newInstance(new URI(pathStr), getConf(), null);
335	      } catch (URISyntaxException e) {
336	        System.err.println("URISyntaxException for " + pathStr + ":" +
337	            StringUtils.stringifyException(e));
338	        return 1;
339	      } catch (InterruptedException e) {
340	        System.err.println("InterruptedException for " + pathStr + ":" +
341	            StringUtils.stringifyException(e));
342	        return 1;
343	      }
344	      DistributedFileSystem dfs = null;
345	      try {
346	        dfs = (DistributedFileSystem) fs;
347	      } catch (ClassCastException e) {
348	        System.err.println("Invalid filesystem for path " + pathStr + ": " +
349	            "needed scheme hdfs, but got: " + fs.getScheme());
350	        return 1;
351	      }
352	      for (int retry = 0; true; ) {
353	        boolean recovered = false;
354	        IOException ioe = null;
355	        try {
356	          recovered = dfs.recoverLease(new Path(pathStr));
357	        } catch (FileNotFoundException e) {
358	          System.err.println("recoverLease got exception: " + e.getMessage());
359	          System.err.println("Giving up on recoverLease for " + pathStr +
360	              " after 1 try");
361	          return 1;
362	        } catch (IOException e) {
363	          ioe = e;
364	        }
365	        if (recovered) {
366	          System.out.println("recoverLease SUCCEEDED on " + pathStr); 
367	          return 0;
368	        }
369	        if (ioe != null) {
370	          System.err.println("recoverLease got exception: " +
371	              ioe.getMessage());
372	        } else {
373	          System.err.println("recoverLease returned false.");
374	        }
375	        retry++;
376	        if (retry >= maxRetries) {
377	          break;
378	        }
379	        System.err.println("Retrying in " + TIMEOUT_MS + " ms...");
380	        Uninterruptibles.sleepUninterruptibly(TIMEOUT_MS,
381	            TimeUnit.MILLISECONDS);
382	        System.err.println("Retry #" + retry);
383	      }
384	      System.err.println("Giving up on recoverLease for " + pathStr + " after " +
385	          maxRetries + (maxRetries == 1 ? " try." : " tries."));
386	      return 1;
387	    }
388	  }
