390	  /**
391	   * The command for getting help about other commands.
392	   */
393	  private class HelpCommand extends DebugCommand {
394	    HelpCommand() {
395	      super("help",
396	"help [command-name]",
397	"  Get help about a command.");
398	    }
399	
400	    int run(List<String> args) {
401	      DebugCommand command = popCommand(args);
402	      if (command == null) {
403	        printUsage();
404	        return 0;
405	      }
406	      System.out.println(command.usageText);
407	      System.out.println(command.helpText + System.lineSeparator());
408	      return 0;
409	    }
410	  }
411	
412	  public DebugAdmin(Configuration conf) {
413	    super(conf);
414	  }
415	
416	  private DebugCommand popCommand(List<String> args) {
417	    String commandStr = (args.size() == 0) ? "" : args.get(0);
418	    if (commandStr.startsWith("-")) {
419	      commandStr = commandStr.substring(1);
420	    }
421	    for (DebugCommand command : DEBUG_COMMANDS) {
422	      if (command.name.equals(commandStr)) {
423	        args.remove(0);
424	        return command;
425	      }
426	    }
427	    return null;
428	  }
429	
430	  public int run(String[] argv) {
431	    LinkedList<String> args = new LinkedList<String>();
432	    for (int j = 0; j < argv.length; ++j) {
433	      args.add(argv[j]);
434	    }
435	    DebugCommand command = popCommand(args);
436	    if (command == null) {
437	      printUsage();
438	      return 0;
439	    }
440	    try {
441	      return command.run(args);
442	    } catch (IOException e) {
443	      System.err.println("IOException: " +
444	          StringUtils.stringifyException(e));
445	      return 1;
446	    } catch (RuntimeException e) {
447	      System.err.println("RuntimeException: " +
448	          StringUtils.stringifyException(e));
449	      return 1;
450	    }
451	  }
452	
453	  private void printUsage() {
454	    System.out.println("Usage: hdfs debug <command> [arguments]\n");
455	    System.out.println("These commands are for advanced users only.\n");
456	    System.out.println("Incorrect usages may result in data loss. " +
457	        "Use at your own risk.\n");
458	    for (DebugCommand command : DEBUG_COMMANDS) {
459	      if (!command.name.equals("help")) {
460	        System.out.println(command.usageText);
461	      }
462	      System.out.println();
463	      ToolRunner.printGenericCommandUsage(System.out);
464	    }
465	  }
466	
467	  public static void main(String[] argsArray) throws Exception {
468	    DebugAdmin debugAdmin = new DebugAdmin(new Configuration());
469	    int res = ToolRunner.run(debugAdmin, argsArray);
470	    System.exit(res);
471	  }
472	}
